/** The CLI, before a product's actions are written into it (generate.ts cliSource). */
export const CLI_SOURCE: string = "#!/usr/bin/env node\n// A command line tool for one Muse Muse product, generated from its musemuse.json. One file, no dependencies, Node 18+.\n// Built with Muse Muse, a hackathon concept. Not an official Meta product.\n\"use strict\";\n\nconst PRODUCT = /*__MUSE_PRODUCT__*/ { slug: \"example\", name: \"Example\", tagline: \"\", liveUrl: \"http://localhost\", mcpUrl: \"\", actions: [] };\nconst VERSION = \"1.0.0\";\nconst DEFAULT_TIMEOUT_S = 120;\nconst USAGE_ERROR = 2;\nconst CALL_ERROR = 1;\n\nclass UsageError extends Error {}\n\n/** Manifests and replies come from elsewhere: nothing a terminal would act on gets printed, only tabs and new lines. */\nfunction safe(text) {\n  return String(text).replace(/[\\u0000-\\u0008\\u000b-\\u001f\\u007f-\\u009f]/g, \"\");\n}\n\nfunction out(text) {\n  process.stdout.write(`${safe(text)}\\n`);\n}\n\nfunction err(text) {\n  process.stderr.write(`${safe(text)}\\n`);\n}\n\n/** JSON as text. JSON.stringify leaves DEL and C1 characters raw, so they are escaped: the value stays exact and safe() has nothing to cut. */\nfunction jsonText(value, indent) {\n  return JSON.stringify(value, null, indent).replace(/[\\u007f-\\u009f]/g, (c) => `\\\\u${c.charCodeAt(0).toString(16).padStart(4, \"0\")}`);\n}\n\n/** The tool's own options. Each short form gives way to a field of the same name, and each --cli- form always means the tool. */\nconst TOOL_OPTIONS = [\"help\", \"json\", \"input\", \"input-file\", \"timeout\"];\n\n/** True while errors should come out as JSON, so a failure before the arguments are read still follows --json. */\nlet jsonMode = false;\n\n/** recipeText and recipe-text both name the field recipeText. */\nfunction flagKey(name) {\n  return name.toLowerCase().replace(/[-_]/g, \"\");\n}\n\nfunction findAction(name) {\n  return PRODUCT.actions.find((a) => a.name === name || a.name === name.replace(/-/g, \"_\"));\n}\n\nfunction fieldsOf(action) {\n  const props = action.input && typeof action.input.properties === \"object\" && action.input.properties ? action.input.properties : {};\n  const required = Array.isArray(action.input && action.input.required) ? action.input.required : [];\n  return Object.keys(props).map((name) => ({ name, schema: props[name] || {}, required: required.includes(name) }));\n}\n\nfunction typeOf(schema) {\n  if (Array.isArray(schema.enum) && schema.enum.length && !schema.type) return typeof schema.enum[0];\n  return Array.isArray(schema.type) ? schema.type.find((t) => t !== \"null\") || \"string\" : schema.type || \"string\";\n}\n\nfunction fieldHint(field) {\n  const type = typeOf(field.schema);\n  const choices = Array.isArray(field.schema.enum) ? ` (${field.schema.enum.join(\", \").replace(/\\s+/g, \" \")})` : \"\";\n  const about = field.schema.description ? `  ${String(field.schema.description).replace(/\\s+/g, \" \")}` : \"\";\n  return `  --${field.name} <${type}>${choices}${field.required ? \" required\" : \"\"}${about}`;\n}\n\nfunction mainHelp() {\n  const lines = [\n    `${PRODUCT.name}${PRODUCT.tagline ? `: ${PRODUCT.tagline}` : \"\"}`,\n    \"\",\n    `Usage: ${PRODUCT.slug} <action> [--field value ...] [--json]`,\n    \"\",\n    \"Actions:\",\n    ...PRODUCT.actions.map((a) => `  ${a.name}  ${a.description}`),\n    \"\",\n    \"Options:\",\n    \"  --help, -h          Show this help, or an action's fields after its name\",\n    \"  --json              Print only JSON. With --help, the actions and their input schemas\",\n    \"  --input <json>      The action's whole input as JSON. '-' reads it from stdin\",\n    \"  --input-file <path> Read the action's input from a JSON file\",\n    `  --timeout <seconds> How long to wait for a reply (default ${DEFAULT_TIMEOUT_S})`,\n    \"  --version           Show the version\",\n    \"\",\n    \"An action's field with one of these names takes that flag. --cli-help, --cli-json, --cli-input <json>,\",\n    \"--cli-input-file <path> and --cli-timeout <seconds> always mean the options above.\",\n    \"\",\n    `It calls the live product at ${PRODUCT.liveUrl}`,\n    \"Built with Muse Muse. Not an official Meta product.\",\n  ];\n  return lines.join(\"\\n\");\n}\n\nfunction actionHelp(action) {\n  const fields = fieldsOf(action);\n  const lines = [`${action.name}: ${action.description}`, \"\", `Usage: ${PRODUCT.slug} ${action.name}${fields.length ? \" [--field value ...]\" : \"\"} [--json]`];\n  if (fields.length) lines.push(\"\", \"Fields:\", ...fields.map(fieldHint));\n  const taken = TOOL_OPTIONS.filter((o) => fields.some((f) => flagKey(f.name) === flagKey(o)));\n  if (taken.length) lines.push(\"\", `A field has the flag ${taken.map((o) => `--${o}`).join(\", \")} here. For the tool's own option, use ${taken.map((o) => `--cli-${o}`).join(\", \")}.`);\n  return lines.join(\"\\n\");\n}\n\nfunction coerce(field, raw) {\n  const type = typeOf(field.schema);\n  if (type === \"number\" || type === \"integer\") {\n    const value = Number(raw);\n    if (raw === \"\" || !Number.isFinite(value) || (type === \"integer\" && !Number.isInteger(value))) throw new UsageError(`--${field.name} must be ${type === \"integer\" ? \"a whole number\" : \"a number\"}.`);\n    return value;\n  }\n  if (type === \"boolean\") {\n    if (raw === \"true\") return true;\n    if (raw === \"false\") return false;\n    throw new UsageError(`--${field.name} must be true or false.`);\n  }\n  if (type === \"array\" || type === \"object\") {\n    try {\n      return JSON.parse(raw);\n    } catch {\n      throw new UsageError(`--${field.name} must be JSON.`);\n    }\n  }\n  return raw;\n}\n\nfunction readStdin() {\n  return require(\"node:fs\").readFileSync(0, \"utf8\");\n}\n\nfunction parseInput(text, source) {\n  let value;\n  try {\n    value = JSON.parse(text);\n  } catch {\n    throw new UsageError(`${source} isn't valid JSON.`);\n  }\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new UsageError(`${source} must be a JSON object.`);\n  return value;\n}\n\n/** Splits the arguments after the action into the input and the tool's own options. */\nfunction parseArgs(action, args) {\n  const opts = { json: false, help: false, timeoutS: DEFAULT_TIMEOUT_S };\n  const fields = fieldsOf(action);\n  const byKey = new Map(fields.map((f) => [flagKey(f.name), f]));\n  let input = {};\n  const named = {};\n  for (let i = 0; i < args.length; i++) {\n    const arg = args[i];\n    if (!arg.startsWith(\"--\")) {\n      if (arg === \"-h\") {\n        opts.help = true;\n        continue;\n      }\n      throw new UsageError(`Unexpected argument: ${arg}`);\n    }\n    const eq = arg.indexOf(\"=\");\n    const name = eq > 0 ? arg.slice(2, eq) : arg.slice(2);\n    const inline = eq > 0 ? arg.slice(eq + 1) : undefined;\n    const value = () => {\n      if (inline !== undefined) return inline;\n      if (i + 1 >= args.length) throw new UsageError(`--${name} needs a value.`);\n      return args[++i];\n    };\n    const forTool = name.startsWith(\"cli-\") && TOOL_OPTIONS.includes(name.slice(4));\n    const field = forTool ? undefined : byKey.get(flagKey(name));\n    if (field) {\n      const bare = typeOf(field.schema) === \"boolean\" && inline === undefined && (i + 1 >= args.length || args[i + 1].startsWith(\"--\"));\n      named[field.name] = bare ? true : coerce(field, value());\n      continue;\n    }\n    const negated = !forTool && name.startsWith(\"no-\") ? byKey.get(flagKey(name.slice(3))) : undefined;\n    if (negated && typeOf(negated.schema) === \"boolean\") {\n      named[negated.name] = false;\n      continue;\n    }\n    const option = forTool ? name.slice(4) : name;\n    if (option === \"json\") opts.json = true;\n    else if (option === \"help\") opts.help = true;\n    else if (option === \"input\") {\n      const text = value();\n      input = parseInput(text === \"-\" ? readStdin() : text, `--${name}`);\n    } else if (option === \"input-file\") {\n      const file = value();\n      let text;\n      try {\n        text = require(\"node:fs\").readFileSync(file, \"utf8\");\n      } catch {\n        throw new UsageError(`Can't read ${file}.`);\n      }\n      input = parseInput(text, file);\n    } else if (option === \"timeout\") {\n      opts.timeoutS = Number(value());\n      if (!(opts.timeoutS > 0)) throw new UsageError(`--${name} must be a number of seconds.`);\n    } else {\n      const known = fields.length ? ` It takes ${fields.map((f) => `--${f.name}`).join(\", \")}.` : \" It takes no fields.\";\n      throw new UsageError(`${action.name} has no field --${name}.${known}`);\n    }\n  }\n  const body = { ...input, ...named };\n  if (!opts.help) {\n    const missing = fields.filter((f) => f.required && body[f.name] === undefined).map((f) => `--${f.name}`);\n    if (missing.length) throw new UsageError(`${action.name} needs ${missing.join(\", \")}.`);\n  }\n  return { body, opts };\n}\n\nasync function callAction(action, body, timeoutS) {\n  if (typeof fetch !== \"function\") throw new Error(\"This tool needs Node 18 or newer.\");\n  const url = `${PRODUCT.liveUrl.replace(/\\/+$/, \"\")}/api/actions/${encodeURIComponent(action.name)}`;\n  let res;\n  try {\n    res = await fetch(url, {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\", accept: \"application/json\", \"user-agent\": `MuseMuse-CLI/${VERSION}` },\n      body: JSON.stringify(body),\n      redirect: \"error\",\n      signal: AbortSignal.timeout(timeoutS * 1000),\n    });\n  } catch (cause) {\n    const timedOut = cause && (cause.name === \"TimeoutError\" || cause.name === \"AbortError\");\n    return { ok: false, status: null, message: timedOut ? `${action.name} took longer than ${timeoutS} s and was stopped.` : `Couldn't reach ${PRODUCT.name} to run ${action.name}.` };\n  }\n  const text = await res.text();\n  if (!res.ok) return { ok: false, status: res.status, message: `${action.name} failed with HTTP ${res.status}: ${text.slice(0, 2000) || \"(empty body)\"}` };\n  try {\n    return { ok: true, reply: JSON.parse(text) };\n  } catch {\n    return { ok: false, status: res.status, message: `${action.name} returned a reply that isn't JSON: ${text.slice(0, 2000)}` };\n  }\n}\n\n/** Whether these arguments ask for JSON, by the same rule parseArgs goes by. A value that happens to read --json counts too, for errors only. */\nfunction wantsJson(args, action) {\n  if (args.includes(\"--cli-json\")) return true;\n  if (!args.includes(\"--json\")) return false;\n  return !(action && fieldsOf(action).some((f) => flagKey(f.name) === \"json\"));\n}\n\nasync function main(argv) {\n  const isJsonFlag = (a) => a === \"--json\" || a === \"--cli-json\";\n  const first = argv.find((a) => !isJsonFlag(a));\n  // An action's name comes first, so one called list or help runs. Those words only mean help when no action has them.\n  const action = first !== undefined && !first.startsWith(\"-\") ? findAction(first) : undefined;\n  const at = first === undefined ? argv.length : argv.indexOf(first);\n  const leadingJson = at > 0;\n  const rest = argv.slice(at + 1);\n  jsonMode = leadingJson || wantsJson(rest, action);\n  if (first === undefined || first === \"--help\" || first === \"--cli-help\" || first === \"-h\" || (!action && (first === \"help\" || first === \"list\"))) {\n    if (jsonMode) out(jsonText({ name: PRODUCT.name, tagline: PRODUCT.tagline, url: PRODUCT.liveUrl, mcp: PRODUCT.mcpUrl, actions: PRODUCT.actions.map((a) => ({ name: a.name, description: a.description, input: a.input })) }));\n    else out(mainHelp());\n    return first === undefined && !jsonMode ? USAGE_ERROR : 0;\n  }\n  if (first === \"--version\") {\n    out(VERSION);\n    return 0;\n  }\n  if (!action) throw new UsageError(`${PRODUCT.slug} has no action called ${first}. Run it with --help to see them.`);\n  const { body, opts } = parseArgs(action, rest);\n  const json = leadingJson || opts.json;\n  if (opts.help) {\n    if (json) out(jsonText({ name: action.name, description: action.description, input: action.input }));\n    else out(actionHelp(action));\n    return 0;\n  }\n  const result = await callAction(action, body, opts.timeoutS);\n  if (!result.ok) {\n    if (json) out(jsonText({ error: { message: result.message, status: result.status } }));\n    else err(result.message);\n    return CALL_ERROR;\n  }\n  out(json ? jsonText(result.reply) : jsonText(result.reply, 2));\n  return 0;\n}\n\nmain(process.argv.slice(2)).then(\n  (code) => {\n    process.exitCode = code;\n  },\n  (cause) => {\n    const usage = cause instanceof UsageError;\n    if (jsonMode) out(jsonText({ error: { message: cause.message, status: null } }));\n    else err(usage ? `${cause.message}\\nRun ${PRODUCT.slug} --help to see what it takes.` : String(cause.message || cause));\n    process.exitCode = usage ? USAGE_ERROR : CALL_ERROR;\n  },\n);\n";

/** What runs each output against the live product, in the Prove it stage's sandbox. */
export const PROVE_RUNNER_SOURCE: string = "// Prove it (docs/PRODUCT_OUTPUTS.md): runs a product's outputs against the live product, as a person would, with curl and\n// node in a throwaway sandbox. Every command's real output and time go to results.json, which the platform turns into\n// each output's result and the terminal scene Demo Studio records. Written into the sandbox by the platform before each\n// run. No dependencies.\n//   node prove-runner.mjs <spec.json>\nimport { spawn } from \"node:child_process\";\nimport { readdirSync, readFileSync, renameSync, statSync, writeFileSync } from \"node:fs\";\nimport path from \"node:path\";\n\n/** What a command's log keeps, so the file and the video stay small. */\nconst OUTPUT_CAP = 64 * 1024;\n/** What's read to judge a command. A product's reply can be large: the MCP route passes up to 1 MB as JSON text. */\nconst PARSE_CAP = 4 * 1024 * 1024;\nconst COMMAND_TIMEOUT_S = 40;\n\nconst spec = JSON.parse(readFileSync(process.argv[2], \"utf8\"));\nconst dir = spec.dir;\nconst resultsPath = path.join(dir, \"results.json\");\nconst results = { startedAt: new Date().toISOString(), finishedAt: null, outputs: {} };\n\nfunction save() {\n  const tmp = `${resultsPath}.tmp`;\n  writeFileSync(tmp, JSON.stringify(results));\n  renameSync(tmp, resultsPath);\n}\n\nconst q = (text) => `'${String(text).replace(/'/g, `'\\\\''`)}'`;\n\n/** Where the product's own sample files are in the copy. The copy is a fork of the product's sandbox. */\nconst FIXTURES_DIR = spec.fixturesDir ?? \"/vercel/app/fixtures\";\n/** The largest sample swapped in: a Vercel Function takes a 4.5 MB body, and base64 adds a third. */\nconst SAMPLE_MAX_BYTES = 3 * 1024 * 1024;\nconst EXT_TYPES = { jpg: \"image/jpeg\", jpeg: \"image/jpeg\", png: \"image/png\", webp: \"image/webp\", gif: \"image/gif\", wav: \"audio/wav\", mp3: \"audio/mpeg\", m4a: \"audio/mp4\", mp4: \"video/mp4\", mov: \"video/quicktime\", pdf: \"application/pdf\" };\n\n/**\n * A manifest example often shortens a file to \"data:image/jpeg;base64,/9j/4AAQ...\", which is fine in the docs but makes\n * every test call fail. Such a value is swapped for the product's own sample of the same kind, from fixtures/, the file\n * its tests already run on. Left as it is when there is no sample of that kind.\n */\nfunction isPlaceholderDataUrl(value) {\n  const m = /^data:([\\w.+-]+\\/[\\w.+-]+)(;[^,]*)?,(.*)$/s.exec(value);\n  if (!m) return false;\n  const body = m[3];\n  return body.length < 200 || /(\\.\\.\\.|\\u2026)$/.test(body.trim());\n}\n\nfunction pickSample(mime, files) {\n  const kind = mime.split(\"/\")[0];\n  const typed = files\n    .map((f) => ({ ...f, type: EXT_TYPES[f.name.split(\".\").pop()?.toLowerCase() ?? \"\"] }))\n    .filter((f) => f.type && f.size > 0 && f.size <= SAMPLE_MAX_BYTES);\n  const exact = typed.filter((f) => f.type === mime);\n  const same = typed.filter((f) => f.type.split(\"/\")[0] === kind);\n  const pool = exact.length ? exact : same;\n  return pool.sort((a, b) => a.size - b.size)[0] ?? null;\n}\n\nlet fixtureFiles = null;\nfunction fixtures() {\n  if (fixtureFiles) return fixtureFiles;\n  try {\n    fixtureFiles = readdirSync(FIXTURES_DIR, { recursive: true })\n      .map(String)\n      .map((name) => ({ name, size: statSync(path.join(FIXTURES_DIR, name)).size }));\n  } catch {\n    fixtureFiles = [];\n  }\n  return fixtureFiles;\n}\n\nfunction withSamples(value) {\n  if (typeof value === \"string\" && isPlaceholderDataUrl(value)) {\n    const mime = /^data:([^;,]+)/.exec(value)[1];\n    const file = pickSample(mime, fixtures());\n    if (!file) return value;\n    return `data:${file.type};base64,${readFileSync(path.join(FIXTURES_DIR, file.name)).toString(\"base64\")}`;\n  }\n  if (Array.isArray(value)) return value.map(withSamples);\n  if (value && typeof value === \"object\") return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, withSamples(v)]));\n  return value;\n}\n\n/** Calls with real samples in place of shortened ones. Runs once, before any call. */\nfunction useSamples() {\n  const swap = (call) => (call ? { ...call, args: withSamples(call.args) } : call);\n  spec.calls = spec.calls.map(swap);\n  spec.cliCall = swap(spec.cliCall);\n  spec.gadgetCall = swap(spec.gadgetCall);\n}\n\n/** A body too long for one command line goes in a file next to the run: Linux caps one argument at 128 KB. */\nconst INLINE_MAX = 32 * 1024;\nlet bodyFiles = 0;\nfunction bodyFile(text) {\n  const file = path.join(dir, `call-${++bodyFiles}.json`);\n  writeFileSync(file, text);\n  return file;\n}\n\n/** Runs one command in bash, combining its output, and never throws. A command that runs too long is stopped. */\nfunction shell(command, timeoutS = COMMAND_TIMEOUT_S) {\n  return new Promise((resolve) => {\n    const started = Date.now();\n    const child = spawn(\"bash\", [\"-c\", command], { cwd: dir, stdio: [\"ignore\", \"pipe\", \"pipe\"], detached: true });\n    let full = \"\";\n    const take = (chunk) => {\n      if (full.length < PARSE_CAP) full += chunk.toString(\"utf8\");\n    };\n    child.stdout.on(\"data\", take);\n    child.stderr.on(\"data\", take);\n    let timedOut = false;\n    const timer = setTimeout(() => {\n      timedOut = true;\n      try {\n        process.kill(-child.pid, \"SIGKILL\");\n      } catch {\n        // Already gone.\n      }\n    }, timeoutS * 1000);\n    const finish = (exitCode) => {\n      clearTimeout(timer);\n      resolve({ command, output: full.slice(0, OUTPUT_CAP), full, exitCode, timedOut, seconds: (Date.now() - started) / 1000 });\n    };\n    child.on(\"error\", () => finish(127));\n    child.on(\"close\", (code) => finish(timedOut ? 124 : (code ?? 1)));\n  });\n}\n\n/** Adds a finished command to an output's log and saves, so a stopped run still shows what it did. */\nfunction logStep(result, caption, ran, ok) {\n  result.steps.push({ caption, command: ran.command, output: ran.output, ok, exitCode: ran.exitCode, seconds: ran.seconds });\n  save();\n}\n\nfunction start(id) {\n  const result = { ok: false, steps: [], facts: {} };\n  results.outputs[id] = result;\n  return result;\n}\n\n/** Stands in for a download when the site can't serve the file here (a test run against a site without these routes). */\nasync function getFile(result, caption, url, file) {\n  if (!url) {\n    const ran = await shell(`ls -l ${q(file)}`);\n    result.facts.downloaded = false;\n    logStep(result, \"Find the file, put here directly\", ran, ran.exitCode === 0);\n    return ran.exitCode === 0;\n  }\n  const ran = await shell(`curl -fsSL --max-time 30 ${q(url)} -o ${q(file)} && ls -l ${q(file)}`);\n  result.facts.downloaded = ran.exitCode === 0;\n  logStep(result, caption, ran, ran.exitCode === 0);\n  return ran.exitCode === 0;\n}\n\nfunction parseJson(text) {\n  try {\n    return JSON.parse(text);\n  } catch {\n    return null;\n  }\n}\n\n// The address and body come first: a video shows only the start of a long command, and these say what the call is.\nconst mcpCommand = (body, maxTime = 30) => {\n  const text = JSON.stringify(body);\n  const data = text.length > INLINE_MAX ? `@${bodyFile(text)}` : text;\n  return `curl -sS -X POST ${q(spec.mcpUrl)} -d ${q(data)} -H 'content-type: application/json' -H 'accept: application/json, text/event-stream' --max-time ${maxTime}`;\n};\n\nasync function proveMcp() {\n  const result = start(\"mcp\");\n  result.facts = { listed: [], missing: [], called: [], notCalled: spec.notCalled };\n  const hello = await shell(\n    mcpCommand({\n      jsonrpc: \"2.0\",\n      id: 1,\n      method: \"initialize\",\n      params: { protocolVersion: \"2025-06-18\", capabilities: {}, clientInfo: { name: \"muse-muse-prove-it\", version: \"1.0.0\" } },\n    }),\n  );\n  const server = parseJson(hello.full)?.result?.serverInfo;\n  logStep(result, \"Connect to the MCP server\", hello, Boolean(server));\n  if (!server) {\n    result.facts.error = \"The MCP server didn't answer initialize.\";\n    return;\n  }\n\n  const list = await shell(mcpCommand({ jsonrpc: \"2.0\", id: 2, method: \"tools/list\" }));\n  const tools = parseJson(list.full)?.result?.tools;\n  const listed = Array.isArray(tools) ? tools : [];\n  result.facts.listed = listed.map((t) => t.name);\n  result.facts.missing = spec.actionNames.filter((name) => !result.facts.listed.includes(name));\n  const schemasOk = listed.every((t) => t.inputSchema?.type === \"object\");\n  const listedOk = Array.isArray(tools) && result.facts.missing.length === 0 && schemasOk;\n  logStep(result, `List its tools: ${listed.length} found`, list, listedOk);\n  if (!listedOk) {\n    result.facts.error = result.facts.missing.length ? `tools/list left out ${result.facts.missing.join(\", \")}.` : \"tools/list didn't give a usable list.\";\n    return;\n  }\n\n  let id = 3;\n  for (const call of spec.calls) {\n    const ran = await shell(mcpCommand({ jsonrpc: \"2.0\", id: id++, method: \"tools/call\", params: { name: call.name, arguments: call.args } }, 130), 140);\n    const body = parseJson(ran.full);\n    const toolResult = body?.result;\n    const ok = Boolean(toolResult) && toolResult.isError !== true && Array.isArray(toolResult.content) && toolResult.content.length > 0;\n    const error = ok ? undefined : String(toolResult?.content?.[0]?.text ?? body?.error?.message ?? ran.output).slice(0, 400);\n    result.facts.called.push({ name: call.name, ok, ...(error ? { error } : {}) });\n    // VERIFY_AGENTS: the platform grades the reply itself, so no second call is needed. Without it, results.json is as it was.\n    if (spec.agentCheck && ok) (result.facts.agentReplies ??= []).push({ name: call.name, text: String(toolResult.content[0]?.text ?? \"\") });\n    logStep(result, `Call ${call.name}`, ran, ok);\n  }\n  const called = result.facts.called;\n  result.ok = called.length === 0 || called.some((c) => c.ok);\n  if (!result.ok) result.facts.error = `Every tool call failed. ${called[0]?.error ?? \"\"}`.trim();\n}\n\n/** What a product answers when the input is wrong, and not when the call or the product is broken. */\nconst REFUSED_STATUS = [400, 413, 422];\n\nasync function proveCli() {\n  const result = start(\"cli\");\n  result.facts = { actionsInHelp: [], called: null, jsonOk: false };\n  const file = `${spec.slug}.cjs`;\n  if (!(await getFile(result, \"Download the CLI\", spec.downloads?.cli, file))) {\n    result.facts.error = \"The CLI didn't download.\";\n    return;\n  }\n  const help = await shell(`node ${q(file)} --help`);\n  const inHelp = spec.actionNames.filter((name) => help.full.includes(name));\n  result.facts.actionsInHelp = inHelp;\n  const helpOk = help.exitCode === 0 && inHelp.length === spec.actionNames.length;\n  logStep(result, \"Ask it for help\", help, helpOk);\n  if (!helpOk) {\n    result.facts.error = help.exitCode === 0 ? \"--help left out some actions.\" : `--help exited with ${help.exitCode}.`;\n    return;\n  }\n  const listed = await shell(`node ${q(file)} --help --json`);\n  const parsed = parseJson(listed.full);\n  const listOk = listed.exitCode === 0 && Array.isArray(parsed?.actions) && parsed.actions.length === spec.actionNames.length;\n  logStep(result, \"List its actions as JSON\", listed, listOk);\n  if (!listOk) {\n    result.facts.error = \"--help --json didn't print the actions as JSON.\";\n    return;\n  }\n  // An action the MCP call showed working, so a poor sample for the first one doesn't count against the CLI.\n  const worked = results.outputs.mcp?.facts.called ?? [];\n  const known = spec.calls.find((c) => worked.some((d) => d.name === c.name && d.ok));\n  const call = known ?? spec.cliCall;\n  if (!call) {\n    result.ok = true;\n    return;\n  }\n  // The --cli- forms, because the action may have a field called input, json or timeout.\n  const args = JSON.stringify(call.args);\n  const input = args.length > INLINE_MAX ? `--cli-input-file ${q(bodyFile(args))}` : `--cli-input ${q(args)}`;\n  const ran = await shell(`node ${q(file)} ${q(call.name)} ${input} --cli-json --cli-timeout 120`, 130);\n  const reply = parseJson(ran.full);\n  // Nothing showed this input working, and the action answered that it won't take it. The CLI did its job.\n  if (!known && ran.exitCode === 1 && REFUSED_STATUS.includes(reply?.error?.status)) {\n    result.facts.refused = call.name;\n    logStep(result, `${call.name} refused the sample input`, ran, true);\n    result.ok = true;\n    return;\n  }\n  const printedHelp = Array.isArray(reply?.actions) && reply?.mcp !== undefined;\n  const ok = ran.exitCode === 0 && reply !== null && reply?.error === undefined && !printedHelp;\n  result.facts.called = call.name;\n  result.facts.jsonOk = ok;\n  logStep(result, `Run ${call.name} and print JSON`, ran, ok);\n  if (printedHelp) result.facts.error = `It printed its help instead of running ${call.name}.`;\n  else if (!ok) result.facts.error = `${call.name} ended with exit code ${ran.exitCode}. ${String(reply?.error?.message ?? ran.output).slice(0, 300)}`.trim();\n  result.ok = ok;\n}\n\nasync function provePlugin() {\n  const result = start(\"claude_plugin\");\n  const file = `${spec.slug}-claude-plugin.zip`;\n  if (!(await getFile(result, \"Download the plugin\", spec.downloads?.claudePlugin, file))) {\n    result.facts.error = \"The plugin didn't download.\";\n    return;\n  }\n  const ran = await shell(`node prove-check-plugin.mjs ${q(file)} ${q(spec.pluginName)} ${q(spec.mcpUrl)} ${q(spec.skillName)}`);\n  logStep(result, \"Check its manifest and MCP address\", ran, ran.exitCode === 0);\n  result.ok = ran.exitCode === 0;\n  if (!result.ok) result.facts.error = ran.output.trim().split(\"\\n\").filter((l) => l.startsWith(\"FAILED\")).join(\" \").slice(0, 400) || \"The check failed.\";\n}\n\n/** The gadget's own test of each declared type, as its SDK checks a call. A boolean is no integer, and null is nothing. */\nconst GADGET_TYPES = {\n  string: (v) => typeof v === \"string\",\n  integer: (v) => Number.isInteger(v),\n  number: (v) => typeof v === \"number\" && Number.isFinite(v),\n  boolean: (v) => typeof v === \"boolean\",\n  object: (v) => !!v && typeof v === \"object\" && !Array.isArray(v),\n  array: (v) => Array.isArray(v),\n};\nconst GADGET_CALL_TIMEOUT_S = 130;\n\n/**\n * The input a gadget passes on, checked the way its SDK checks a call before it runs the command: every required field\n * there, every field its declared type, and only declared fields passed on. An optional field set to null is left out,\n * since Muse leaves out a field it has nothing for. Gives { input }, or { problem } in the SDK's words.\n */\nfunction gadgetInput(command, args) {\n  const required = command.required ?? {};\n  const declared = { ...(command.optional ?? {}), ...required };\n  for (const name of Object.keys(required)) if (!Object.hasOwn(args, name) || args[name] === null) return { problem: `${name} is required`, missing: true };\n  const input = {};\n  for (const [name, param] of Object.entries(declared)) {\n    if (!Object.hasOwn(args, name) || args[name] === null) continue;\n    const fits = GADGET_TYPES[param?.type];\n    if (!fits || !fits(args[name])) return { problem: `${name} must be ${/^[aeiou]/.test(String(param?.type)) ? \"an\" : \"a\"} ${param?.type}` };\n    input[name] = args[name];\n  }\n  return { input };\n}\n\nasync function proveGadget() {\n  const result = start(\"gadget\");\n  result.facts = { commands: 0, called: null };\n  const file = `${spec.slug}-muse-gadget.zip`;\n  if (!(await getFile(result, \"Download the gadget pack\", spec.downloads?.gadget, file))) {\n    result.facts.error = \"The gadget pack didn't download.\";\n    return;\n  }\n  const checked = await shell(`node prove-check-gadget.mjs ${q(file)} ${q(spec.slug)} ${q(spec.gadgetPrefix)}`);\n  const lines = checked.full.split(\"\\n\");\n  result.facts.commands = lines.filter((l) => / follows the SDK's rules$/.test(l)).length;\n  logStep(result, \"Unpack it and check every command by the SDK's rules\", checked, checked.exitCode === 0);\n  if (checked.exitCode !== 0) {\n    result.facts.error = lines.filter((l) => l.startsWith(\"FAILED\")).join(\" \").slice(0, 400) || \"The check failed.\";\n    return;\n  }\n  const folder = /^unpacked to (.+)$/m.exec(checked.full)?.[1];\n  // An action the MCP call showed working, as for the CLI. No call at all when one more wouldn't fit the budget.\n  const worked = results.outputs.mcp?.facts.called ?? [];\n  const known = spec.calls.find((c) => worked.some((d) => d.name === c.name && d.ok));\n  const call = spec.gadgetCall ? (known ?? spec.gadgetCall) : null;\n  if (!call || !folder) {\n    result.ok = true;\n    return;\n  }\n  let command = null;\n  for (const name of readdirSync(path.join(folder, \"commands.d\"))) {\n    const parsed = parseJson(readFileSync(path.join(folder, \"commands.d\", name), \"utf8\"));\n    if (parsed?.exec?.[2] === call.name) command = { name: name.replace(/\\.json$/, \"\"), spec: parsed };\n  }\n  if (!command) {\n    result.facts.error = `No command runs ${call.name}.`;\n    return;\n  }\n  // The gadget checks the input before it runs anything. A sample it would refuse is a poor sample, unless the MCP call\n  // showed the product taking it: then the pack declares a type the product doesn't ask for, and the pack is wrong.\n  const checkedInput = gadgetInput(command.spec, call.args);\n  if (checkedInput.problem) {\n    if (known && !checkedInput.missing) {\n      result.facts.error = `${command.name} would refuse an input the product takes: ${checkedInput.problem}.`;\n      return;\n    }\n    result.facts.refused = call.name;\n    result.facts.refusedWhy = checkedInput.problem;\n    result.ok = true;\n    return;\n  }\n  // As the gadget runs it: its declared parameters as JSON on stdin, no shell around the runner, and its timeout, kept to\n  // the wait the MCP and CLI calls get.\n  const input = JSON.stringify(checkedInput.input);\n  const timeoutS = Math.min(GADGET_CALL_TIMEOUT_S, Math.ceil((command.spec.timeout_ms ?? 30_000) / 1000) + 5);\n  const feed = input.length > INLINE_MAX ? `< ${q(bodyFile(input))}` : null;\n  const ran = await shell(feed ? `cd ${q(folder)} && node runner.cjs ${q(call.name)} ${feed}` : `cd ${q(folder)} && printf '%s' ${q(input)} | node runner.cjs ${q(call.name)}`, timeoutS);\n  const reply = parseJson(ran.full);\n  const reason = ran.full.trim().split(\"\\n\").pop() ?? \"\";\n  const status = Number(/HTTP (\\d{3})/.exec(reason)?.[1]);\n  if (!known && ran.exitCode === 1 && REFUSED_STATUS.includes(status)) {\n    result.facts.refused = call.name;\n    logStep(result, `${command.name} refused the sample input`, ran, true);\n    result.ok = true;\n    return;\n  }\n  const ok = ran.exitCode === 0 && reply !== null && typeof reply === \"object\" && !Array.isArray(reply) && reply.error === undefined;\n  result.facts.called = ok ? call.name : null;\n  logStep(result, `Run ${command.name} as the gadget would`, ran, ok);\n  if (!ok) result.facts.error = ran.timedOut ? `${command.name} didn't answer within ${timeoutS} s.` : `${command.name} ended with exit code ${ran.exitCode}. ${reason.slice(0, 300)}`.trim();\n  result.ok = ok;\n}\n\nasync function proveSkillFile() {\n  const result = start(\"skill\");\n  result.facts = { problems: [] };\n  if (!(await getFile(result, \"Download the skill file\", spec.downloads?.skill, \"SKILL.md\"))) {\n    result.facts.error = \"The skill file didn't download.\";\n    return;\n  }\n  const ran = await shell(\"head -n 4 SKILL.md | cut -c1-200\");\n  let text = \"\";\n  try {\n    text = readFileSync(path.join(dir, \"SKILL.md\"), \"utf8\");\n  } catch {\n    // Reported below.\n  }\n  const problems = [];\n  if (!text.startsWith(\"---\\n\")) problems.push(\"it has no front matter\");\n  if (!new RegExp(`^name: \"?${spec.skillName}\"?$`, \"m\").test(text)) problems.push(\"its name is wrong\");\n  if (!/^description: \"/m.test(text)) problems.push(\"it has no description\");\n  for (const name of spec.actionNames) if (!text.includes(`/api/actions/${name}`)) problems.push(`it leaves out ${name}`);\n  result.facts.problems = problems;\n  logStep(result, \"Read the skill file\", ran, problems.length === 0);\n  result.ok = problems.length === 0;\n  if (!result.ok) result.facts.error = `The skill file is wrong: ${problems.join(\", \")}.`;\n}\n\nuseSamples();\nsave();\nfor (const prove of [proveMcp, proveCli, provePlugin, proveGadget, proveSkillFile]) {\n  try {\n    await prove();\n  } catch (err) {\n    console.error(`${prove.name}: ${err}`);\n  }\n  save();\n}\nresults.finishedAt = new Date().toISOString();\nsave();\n";

/** The machine check of the Claude plugin's zip. */
export const PROVE_CHECK_PLUGIN_SOURCE: string = "// Checks a Claude plugin zip by machine: its manifest, its MCP address and its skill, then asks that address for its tools.\n//   node prove-check-plugin.mjs <plugin.zip> <name> <mcp url> <skill name>\nimport { readFileSync } from \"node:fs\";\nimport { inflateRawSync } from \"node:zlib\";\n\nconst [zipPath, name, mcpUrl, skillName] = process.argv.slice(2);\n/** Names `claude plugin validate` keeps for Anthropic's own, as of Claude Code 2.1.314. */\nconst RESERVED = /^(claude|anthropics?)(-|$)|^cc-plugin-|official.*(claude|anthropic)|(claude|anthropic).*official/;\nlet failed = false;\nconst say = (ok, text) => {\n  console.log(`${ok ? \"ok    \" : \"FAILED\"} ${text}`);\n  if (!ok) failed = true;\n};\n\nfunction readZip(zip) {\n  let end = -1;\n  for (let i = zip.length - 22; i >= 0; i--) {\n    if (zip.readUInt32LE(i) === 0x06054b50) {\n      end = i;\n      break;\n    }\n  }\n  if (end < 0) throw new Error(\"it isn't a zip file\");\n  const files = new Map();\n  let at = zip.readUInt32LE(end + 16);\n  for (let n = zip.readUInt16LE(end + 10); n > 0; n--) {\n    const method = zip.readUInt16LE(at + 10);\n    const packed = zip.readUInt32LE(at + 20);\n    const nameLength = zip.readUInt16LE(at + 28);\n    const offset = zip.readUInt32LE(at + 42);\n    const file = zip.subarray(at + 46, at + 46 + nameLength).toString(\"utf8\");\n    const start = offset + 30 + zip.readUInt16LE(offset + 26) + zip.readUInt16LE(offset + 28);\n    const body = zip.subarray(start, start + packed);\n    files.set(file, (method === 8 ? inflateRawSync(body) : body).toString(\"utf8\"));\n    at += 46 + nameLength + zip.readUInt16LE(at + 30) + zip.readUInt16LE(at + 32);\n  }\n  return files;\n}\n\nfunction json(files, file) {\n  try {\n    return JSON.parse(files.get(file) ?? \"\");\n  } catch {\n    return null;\n  }\n}\n\nlet files;\ntry {\n  files = readZip(readFileSync(zipPath));\n} catch (err) {\n  say(false, `can't read the zip: ${err.message}`);\n  process.exit(1);\n}\nfor (const file of files.keys()) console.log(`      ${file}`);\nsay([...files.keys()].every((f) => !f.startsWith(\"/\") && !f.split(\"/\").includes(\"..\")), \"every path stays inside the plugin\");\n\nconst manifest = json(files, \".claude-plugin/plugin.json\");\nsay(manifest?.name === name && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(name), `.claude-plugin/plugin.json is named ${name}`);\nsay(!RESERVED.test(name), `${name} isn't a name reserved for Anthropic's own plugins`);\nsay(typeof manifest?.version === \"string\" && typeof manifest?.description === \"string\", \".claude-plugin/plugin.json has a version and a description\");\n\nconst servers = json(files, \".mcp.json\")?.mcpServers ?? {};\nconst server = servers[name];\nsay(Object.keys(servers).length === 1 && server?.type === \"http\", \".mcp.json has one HTTP server\");\nsay(server?.url === mcpUrl, `.mcp.json points at ${mcpUrl}`);\n\nconst skill = files.get(`skills/${skillName}/SKILL.md`) ?? \"\";\nsay(skill.startsWith(\"---\\n\") && new RegExp(`^name: \"?${skillName}\"?$`, \"m\").test(skill) && /^description: \"/m.test(skill), `skills/${skillName}/SKILL.md has a name and a description`);\n\ntry {\n  const res = await fetch(server?.url ?? mcpUrl, {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\", accept: \"application/json, text/event-stream\" },\n    body: JSON.stringify({ jsonrpc: \"2.0\", id: 1, method: \"tools/list\" }),\n    signal: AbortSignal.timeout(30_000),\n  });\n  const tools = (await res.json())?.result?.tools;\n  say(res.ok && Array.isArray(tools), `that address answers tools/list with ${Array.isArray(tools) ? tools.length : 0} tools`);\n} catch (err) {\n  say(false, `that address didn't answer: ${err.message}`);\n}\nprocess.exit(failed ? 1 : 0);\n";

/** The terminal scene Demo Studio records. */
export const PROVE_SCENE_SOURCE: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Terminal</title>\n<style>\n/* Text stays 100 px from each side: Demo Studio's lowest zoom on a result, 1.15, crops about 84 px off each side of 1280. */\n* { box-sizing: border-box; }\nhtml, body { margin: 0; height: 100%; background: #0d1117; color: #e6edf3; overflow: hidden; }\nbody { display: flex; flex-direction: column; font: 17px/1.5 \"DejaVu Sans Mono\", \"Liberation Mono\", \"Noto Sans Mono\", ui-monospace, Menlo, monospace; }\nheader { flex: none; display: flex; align-items: baseline; justify-content: space-between; gap: 24px; padding: 14px 100px; background: #161b22; border-bottom: 1px solid #30363d; }\nheader b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\nheader span { color: #9da7b3; font-size: 14px; white-space: nowrap; }\nmain { flex: 1; width: 1080px; min-height: 0; margin: 0 auto; overflow: hidden; padding: 16px 0 24px; }\n.block { margin: 0 0 14px; }\n.cmd { white-space: pre-wrap; overflow-wrap: anywhere; }\n.cmd::before { content: \"$ \"; color: #7ee787; }\n.out { white-space: pre-wrap; overflow-wrap: anywhere; color: #c9d1d9; }\n.out.cut { color: #9da7b3; }\n.took { color: #7ee787; font-size: 15px; }\n.took.bad { color: #ff7b72; }\n.wait { color: #9da7b3; }\n</style>\n</head>\n<body>\n<header><b id=\"title\"></b><span id=\"note\"></span></header>\n<main id=\"main\"></main>\n<script>\n(function () {\n  var main = document.getElementById(\"main\");\n  var scene = null;\n  var pause = function (ms) { return new Promise(function (resolve) { setTimeout(resolve, ms); }); };\n  var keep = function () { main.scrollTop = main.scrollHeight; };\n\n  window.loadScene = function (next) {\n    scene = next;\n    document.getElementById(\"title\").textContent = scene.title;\n    document.getElementById(\"note\").textContent = scene.note;\n    document.title = scene.title;\n  };\n\n  // Types the command, shows it waiting for at most a moment (the real time is printed under the output), then prints\n  // the output it really gave.\n  window.playStep = async function (index) {\n    var step = scene.steps[index];\n    var block = document.createElement(\"div\");\n    block.className = \"block\";\n    main.appendChild(block);\n\n    var cmd = document.createElement(\"div\");\n    cmd.className = \"cmd\";\n    block.appendChild(cmd);\n    var text = step.command;\n    var chunk = Math.max(1, Math.ceil(text.length / 24));\n    for (var at = 0; at < text.length; at += chunk) {\n      cmd.textContent = text.slice(0, at + chunk);\n      keep();\n      await pause(40);\n    }\n\n    var wait = document.createElement(\"div\");\n    wait.className = \"wait\";\n    wait.textContent = \"running\";\n    wait.setAttribute(\"aria-busy\", \"true\");\n    block.appendChild(wait);\n    keep();\n    await pause(Math.min(1200, Math.max(300, step.seconds * 1000)));\n    block.removeChild(wait);\n\n    var out = document.createElement(\"div\");\n    out.className = \"out\";\n    out.textContent = step.lines.join(\"\\n\");\n    if (step.lines.length) block.appendChild(out);\n    var took = document.createElement(\"div\");\n    took.className = \"took\" + (step.ok ? \"\" : \" bad\");\n    took.textContent = (step.ok ? \"ok, \" : \"failed, \") + step.took;\n    block.appendChild(took);\n    keep();\n    await pause(300);\n    keep();\n  };\n})();\n</script>\n</body>\n</html>\n";

/** The Muse gadget pack's runner, before a product's address and actions are written into it (gadget.ts). */
export const GADGET_RUNNER_SOURCE: string = "#!/usr/bin/env node\n// Runs one action of a Muse Muse product for a Muse gadget's custom command (docs/PRODUCT_OUTPUTS.md). The gadget's\n// service starts it with no shell and the command's parameters as a JSON object on stdin. It POSTs them to the live\n// product and prints the reply as one JSON object. On a failure it exits 1 with the reason as its last line on stderr,\n// which the gadget hands back to Muse. One file, no dependencies, Node 18+. It never starts another program.\n// Built with Muse Muse, a hackathon concept. Not an official Meta product.\n\"use strict\";\n\nconst PACK = /*__MUSE_GADGET__*/ { liveUrl: \"http://localhost\", actions: {} };\nconst VERSION = \"1.0.0\";\n/** What stdin may hold. A gadget's own parameters are small. */\nconst MAX_INPUT_BYTES = 1024 * 1024;\n/** The gadget keeps 96 KiB of a command's output, so a longer reply would come back cut and no longer JSON. */\nconst MAX_OUTPUT_BYTES = 90 * 1024;\n/** Time left for saying why, before the gadget stops the command at its timeout_ms. */\nconst MARGIN_MS = 1500;\n\n/** One line with nothing a terminal or a log would act on, since replies come from elsewhere. */\nfunction oneLine(text, max = 400) {\n  const flat = String(text).replace(/[\\u0000-\\u001f\\u007f-\\u009f]+/g, \" \").replace(/\\s+/g, \" \").trim();\n  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat;\n}\n\nclass Failure extends Error {}\n\nfunction readStdin() {\n  return new Promise((resolve, reject) => {\n    const chunks = [];\n    let size = 0;\n    process.stdin.on(\"data\", (chunk) => {\n      size += chunk.length;\n      if (size > MAX_INPUT_BYTES) reject(new Failure(`The input is over ${MAX_INPUT_BYTES / 1024} KiB.`));\n      else chunks.push(chunk);\n    });\n    process.stdin.on(\"end\", () => resolve(Buffer.concat(chunks).toString(\"utf8\")));\n    process.stdin.on(\"error\", () => reject(new Failure(\"Couldn't read the input.\")));\n  });\n}\n\nfunction parseInput(text) {\n  if (!text.trim()) return {};\n  let value;\n  try {\n    value = JSON.parse(text);\n  } catch {\n    throw new Failure(\"The input isn't JSON.\");\n  }\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new Failure(\"The input must be a JSON object.\");\n  return value;\n}\n\n/** What an error reply says, in one line. */\nfunction replyReason(text) {\n  try {\n    const body = JSON.parse(text);\n    const said = body && typeof body === \"object\" ? (typeof body.error === \"string\" ? body.error : body.error && body.error.message) || body.message : null;\n    if (typeof said === \"string\" && said.trim()) return oneLine(said, 300);\n  } catch {\n    // Not JSON: say what it was.\n  }\n  return oneLine(text, 300) || \"(empty reply)\";\n}\n\nasync function main() {\n  const name = process.argv[2];\n  const action = typeof name === \"string\" && Object.hasOwn(PACK.actions, name) ? PACK.actions[name] : null;\n  if (!action) throw new Failure(`This pack has no action called ${oneLine(name || \"(none)\", 80)}.`);\n  if (typeof fetch !== \"function\") throw new Failure(\"It needs Node 18 or newer.\");\n  const input = parseInput(await readStdin());\n  const waitMs = Math.max(500, action.timeoutMs - MARGIN_MS);\n  const url = `${PACK.liveUrl.replace(/\\/+$/, \"\")}/api/actions/${encodeURIComponent(name)}`;\n  let res;\n  try {\n    res = await fetch(url, {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\", accept: \"application/json\", \"user-agent\": `MuseMuse-Gadget/${VERSION}` },\n      body: JSON.stringify(input),\n      // The address is fixed in this file. A redirect would send the input somewhere else.\n      redirect: \"error\",\n      signal: AbortSignal.timeout(waitMs),\n    });\n  } catch (cause) {\n    const timedOut = cause && (cause.name === \"TimeoutError\" || cause.name === \"AbortError\");\n    throw new Failure(timedOut ? `${name} took longer than ${Math.round(waitMs / 1000)} s and was stopped.` : `Couldn't reach the product to run ${name}.`);\n  }\n  const text = await res.text();\n  if (!res.ok) throw new Failure(`${name} failed with HTTP ${res.status}: ${replyReason(text)}`);\n  let reply;\n  try {\n    reply = JSON.parse(text);\n  } catch {\n    throw new Failure(`${name} answered with something that isn't JSON.`);\n  }\n  // The gadget takes a JSON object as the result, so anything else is wrapped in one.\n  const object = reply && typeof reply === \"object\" && !Array.isArray(reply) ? reply : { result: reply };\n  // DEL and C1 characters are escaped too, so the value stays exact and nothing in it reaches a log raw.\n  const json = JSON.stringify(object).replace(/[\\u007f-\\u009f]/g, (c) => `\\\\u${c.charCodeAt(0).toString(16).padStart(4, \"0\")}`);\n  if (Buffer.byteLength(json) > MAX_OUTPUT_BYTES) throw new Failure(`${name}'s reply is ${Math.ceil(Buffer.byteLength(json) / 1024)} KiB, more than a gadget passes back (${MAX_OUTPUT_BYTES / 1024} KiB).`);\n  process.stdout.write(`${json}\\n`);\n}\n\nmain().then(\n  () => {\n    process.exitCode = 0;\n  },\n  (cause) => {\n    process.stderr.write(`${oneLine(cause instanceof Failure ? cause.message : `Something went wrong: ${cause && cause.message ? cause.message : cause}`)}\\n`);\n    process.exitCode = 1;\n  },\n);\n";

/** The Muse gadget pack's install.sh, before its names are written into it. */
export const GADGET_INSTALL_SOURCE: string = "#!/usr/bin/env bash\n# Adds this pack's commands to a Muse gadget that runs Meta's Linux Gadget SDK, so your Muse can use the product\n# (README.md). Run it on the gadget, from the unzipped folder, after the SDK is installed and paired with your own Muse\n# account:\n#\n#   sudo bash install.sh\n#\n# It copies the command files to /etc/musegadget/commands.d and the runner to /usr/local/lib/<pack>-gadget, owned by root\n# and writable only by root, then restarts the musegadget service. It never reads or changes your SDK token or pairing.\n# Built with Muse Muse, a hackathon concept. Not an official Meta product.\nset -euo pipefail\n\nPREFIX=__MUSE_GADGET_PREFIX__\nSLUG=__MUSE_GADGET_SLUG__\nCOMMANDS=(__MUSE_GADGET_COMMANDS__)\n\nHERE=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nROOT=\"\"\nDRY_RUN=0\nRESTART=1\nNODE_BIN=\"\"\n\nusage() {\n  cat <<EOF\nUsage: sudo bash install.sh [--node /path/to/node] [--no-restart] [--dry-run]\n\n  --node <path>  The Node.js 18+ to run the commands with. Default: the node on root's PATH, then /usr/bin/node.\n  --no-restart   Don't restart the musegadget service. The commands appear after the next restart.\n  --dry-run      Print what it would do and change nothing. Needs no sudo.\n  --root <dir>   Install under <dir> instead of /, for testing.\nEOF\n}\n\nsay() { printf '%s\\n' \"$*\"; }\nfail() {\n  printf '%s\\n' \"$*\" >&2\n  exit 1\n}\n\nwhile [ $# -gt 0 ]; do\n  case \"$1\" in\n    --dry-run) DRY_RUN=1 ;;\n    --no-restart) RESTART=0 ;;\n    --node)\n      [ $# -ge 2 ] || fail \"--node needs a path.\"\n      NODE_BIN=\"$2\"\n      shift\n      ;;\n    --root)\n      [ $# -ge 2 ] || fail \"--root needs a folder.\"\n      ROOT=\"${2%/}\"\n      case \"$ROOT\" in /*) ;; *) fail \"--root must be a full path.\" ;; esac\n      shift\n      ;;\n    -h | --help)\n      usage\n      exit 0\n      ;;\n    *)\n      usage >&2\n      fail \"Unknown option: $1\"\n      ;;\n  esac\n  shift\ndone\n\n# Runs a step, or in a dry run prints it.\nrun() {\n  if [ \"$DRY_RUN\" = 1 ]; then\n    printf 'would run:'\n    printf ' %q' \"$@\"\n    printf '\\n'\n  else\n    \"$@\"\n  fi\n}\n\nNAME_RE='^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$'\n[[ \"$PREFIX\" =~ ^[a-z][a-z0-9_]*$ && \"$SLUG\" =~ ^[a-z0-9-]+$ ]] || fail \"This pack's name is damaged. Download it again.\"\nfor name in \"${COMMANDS[@]}\"; do\n  [[ \"$name\" =~ $NAME_RE && \"$name\" == \"$PREFIX.\"* ]] || fail \"This pack's command list is damaged. Download it again.\"\ndone\n\nif [ \"$DRY_RUN\" != 1 ] && [ \"$(id -u)\" != 0 ]; then\n  fail \"Run it with sudo: sudo bash install.sh\"\nfi\n\nSDK_DIR=\"$ROOT/opt/musegadget\"\nCMD_DIR=\"$ROOT/etc/musegadget/commands.d\"\nLIB_DIR=\"$ROOT/usr/local/lib/$PREFIX-gadget\"\n\nif [ ! -d \"$SDK_DIR\" ]; then\n  if [ \"$DRY_RUN\" = 1 ]; then\n    say \"note: Meta's Linux Gadget SDK isn't installed here (no /opt/musegadget). A real install would stop.\"\n  else\n    fail \"Meta's Linux Gadget SDK isn't installed here (no /opt/musegadget). Install it and pair it with your own Muse account first: https://github.com/facebookincubator/muse-gadget-sdk/blob/main/linux/README.md\"\n  fi\nfi\n\n# The node to run the commands with. The service runs them with no shell and no PATH of yours, so it needs a full path.\nif [ -z \"$NODE_BIN\" ]; then\n  NODE_BIN=\"$(command -v node || true)\"\n  [ -n \"$NODE_BIN\" ] || NODE_BIN=/usr/bin/node\nfi\ncase \"$NODE_BIN\" in\n  /*) ;;\n  *) fail \"--node must be a full path, like /usr/bin/node.\" ;;\nesac\n[ -x \"$NODE_BIN\" ] || fail \"There's no Node.js at $NODE_BIN. Install Node 18 or newer (sudo apt install nodejs), or name it with --node.\"\n\"$NODE_BIN\" -e 'process.exit(Number(process.versions.node.split(\".\")[0]) >= 18 ? 0 : 1)' || fail \"$NODE_BIN is older than Node 18. Install a newer one, or name it with --node.\"\n\n# The SDK skips commands in a folder that is a link, or that anyone but root can write to.\n[ ! -L \"$CMD_DIR\" ] || fail \"$CMD_DIR is a link. The gadget refuses commands from a linked folder.\"\n[ ! -L \"$LIB_DIR\" ] || fail \"$LIB_DIR is a link. Remove it and run this again.\"\nif [ -d \"$CMD_DIR\" ] && [ -n \"$(find \"$CMD_DIR\" -maxdepth 0 \\( -perm -020 -o -perm -002 \\))\" ]; then\n  fail \"$CMD_DIR can be written by others, so the gadget would refuse every command in it. Fix it with: sudo chmod 755 $CMD_DIR\"\nfi\nowner_of() { stat -c %u -- \"$1\" 2>/dev/null || stat -f %u -- \"$1\"; }\nif [ -d \"$CMD_DIR\" ] && [ \"$(owner_of \"$CMD_DIR\")\" != 0 ]; then\n  fail \"$CMD_DIR isn't owned by root, so the gadget would refuse every command in it. Fix it with: sudo chown root:root $CMD_DIR\"\nfi\n# Another product's pack with the same names would be replaced, so stop. Each pack writes its slug in pack.txt.\nif [ -f \"$LIB_DIR/pack.txt\" ]; then\n  other=\"$(head -n 1 -- \"$LIB_DIR/pack.txt\" | tr -cd 'a-z0-9-')\"\n  [ \"$other\" = \"$SLUG\" ] || fail \"$LIB_DIR belongs to another product's pack ($other). Remove that one with its uninstall.sh first.\"\nfi\nfor name in \"${COMMANDS[@]}\"; do\n  src=\"$HERE/commands.d/$name.json\"\n  [ -f \"$src\" ] && [ ! -L \"$src\" ] || fail \"commands.d/$name.json is missing from this folder. Download the pack again.\"\ndone\n[ -f \"$HERE/runner.cjs\" ] && [ ! -L \"$HERE/runner.cjs\" ] || fail \"runner.cjs is missing from this folder. Download the pack again.\"\n\n# Commands an earlier version of this pack added and this one doesn't have.\nif [ -f \"$LIB_DIR/commands.txt\" ]; then\n  while IFS= read -r old; do\n    [[ \"$old\" =~ $NAME_RE && \"$old\" == \"$PREFIX.\"* ]] || continue\n    keep=0\n    for name in \"${COMMANDS[@]}\"; do [ \"$name\" = \"$old\" ] && keep=1; done\n    [ \"$keep\" = 1 ] || run rm -f -- \"$CMD_DIR/$old.json\"\n  done <\"$LIB_DIR/commands.txt\"\nfi\n\nif [ ! -d \"$CMD_DIR\" ]; then\n  run mkdir -p -- \"$CMD_DIR\"\n  run chown -- 0:0 \"$CMD_DIR\"\n  run chmod -- 0755 \"$CMD_DIR\"\nfi\nrun mkdir -p -- \"$LIB_DIR\"\nrun chown -- 0:0 \"$LIB_DIR\"\nrun chmod -- 0755 \"$LIB_DIR\"\n\n# Each file is written beside its place, then moved in, so the service never reads half of one.\nput() {\n  local src=\"$1\" dest=\"$2\" mode=\"$3\"\n  run cp -- \"$src\" \"$dest.tmp\"\n  run chown -- 0:0 \"$dest.tmp\"\n  run chmod -- \"$mode\" \"$dest.tmp\"\n  run mv -f -- \"$dest.tmp\" \"$dest\"\n}\n\nput \"$HERE/runner.cjs\" \"$LIB_DIR/runner.cjs\" 0755\nrun ln -sfn -- \"$NODE_BIN\" \"$LIB_DIR/node\"\nfor name in \"${COMMANDS[@]}\"; do\n  put \"$HERE/commands.d/$name.json\" \"$CMD_DIR/$name.json\" 0644\ndone\n# What this pack is and added, for an upgrade and for uninstall.sh.\nnote() {\n  local dest=\"$1\"\n  shift\n  if [ \"$DRY_RUN\" = 1 ]; then\n    say \"would write: $dest\"\n  else\n    printf '%s\\n' \"$@\" >\"$dest.tmp\"\n    chown -- 0:0 \"$dest.tmp\"\n    chmod -- 0644 \"$dest.tmp\"\n    mv -f -- \"$dest.tmp\" \"$dest\"\n  fi\n}\nnote \"$LIB_DIR/commands.txt\" \"${COMMANDS[@]}\"\nnote \"$LIB_DIR/pack.txt\" \"$SLUG\"\n\nif [ \"$DRY_RUN\" = 1 ]; then\n  [ \"$RESTART\" = 1 ] && run systemctl restart musegadget\n  say \"Dry run: nothing was changed.\"\n  exit 0\nfi\nif [ \"$RESTART\" = 1 ]; then\n  run systemctl restart musegadget\n  say \"Added ${#COMMANDS[@]} commands and restarted the gadget: ${COMMANDS[*]}\"\nelse\n  say \"Added ${#COMMANDS[@]} commands: ${COMMANDS[*]}. They appear after: sudo systemctl restart musegadget\"\nfi\nsay \"To check: sudo journalctl -u musegadget | grep commands\"\nsay \"To remove them: sudo bash uninstall.sh\"\n";

/** The Muse gadget pack's uninstall.sh, before its names are written into it. */
export const GADGET_UNINSTALL_SOURCE: string = "#!/usr/bin/env bash\n# Removes this pack's commands from a Muse gadget (README.md):\n#\n#   sudo bash uninstall.sh\n#\n# It deletes only what install.sh added: its command files in /etc/musegadget/commands.d and /usr/local/lib/<pack>-gadget,\n# then restarts the musegadget service. Meta's SDK, your SDK token and your pairing stay as they are.\n# Built with Muse Muse, a hackathon concept. Not an official Meta product.\nset -euo pipefail\n\nPREFIX=__MUSE_GADGET_PREFIX__\nSLUG=__MUSE_GADGET_SLUG__\nCOMMANDS=(__MUSE_GADGET_COMMANDS__)\n\nROOT=\"\"\nDRY_RUN=0\nRESTART=1\n\nusage() {\n  cat <<EOF\nUsage: sudo bash uninstall.sh [--no-restart] [--dry-run]\n\n  --no-restart   Don't restart the musegadget service. The commands go away after the next restart.\n  --dry-run      Print what it would do and change nothing. Needs no sudo.\n  --root <dir>   Remove from under <dir> instead of /, for testing.\nEOF\n}\n\nsay() { printf '%s\\n' \"$*\"; }\nfail() {\n  printf '%s\\n' \"$*\" >&2\n  exit 1\n}\n\nwhile [ $# -gt 0 ]; do\n  case \"$1\" in\n    --dry-run) DRY_RUN=1 ;;\n    --no-restart) RESTART=0 ;;\n    --root)\n      [ $# -ge 2 ] || fail \"--root needs a folder.\"\n      ROOT=\"${2%/}\"\n      case \"$ROOT\" in /*) ;; *) fail \"--root must be a full path.\" ;; esac\n      shift\n      ;;\n    -h | --help)\n      usage\n      exit 0\n      ;;\n    *)\n      usage >&2\n      fail \"Unknown option: $1\"\n      ;;\n  esac\n  shift\ndone\n\nrun() {\n  if [ \"$DRY_RUN\" = 1 ]; then\n    printf 'would run:'\n    printf ' %q' \"$@\"\n    printf '\\n'\n  else\n    \"$@\"\n  fi\n}\n\nNAME_RE='^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$'\n[[ \"$PREFIX\" =~ ^[a-z][a-z0-9_]*$ && \"$SLUG\" =~ ^[a-z0-9-]+$ ]] || fail \"This pack's name is damaged. Download it again.\"\n\nif [ \"$DRY_RUN\" != 1 ] && [ \"$(id -u)\" != 0 ]; then\n  fail \"Run it with sudo: sudo bash uninstall.sh\"\nfi\n\nCMD_DIR=\"$ROOT/etc/musegadget/commands.d\"\nLIB_DIR=\"$ROOT/usr/local/lib/$PREFIX-gadget\"\n\n# Another product's pack with the same names stays as it is.\nif [ -f \"$LIB_DIR/pack.txt\" ]; then\n  other=\"$(head -n 1 -- \"$LIB_DIR/pack.txt\" | tr -cd 'a-z0-9-')\"\n  [ \"$other\" = \"$SLUG\" ] || fail \"$LIB_DIR belongs to another product's pack ($other), so nothing was removed. Use that pack's uninstall.sh.\"\nfi\n\n# This version's commands, and any an earlier version added.\nnames=(\"${COMMANDS[@]}\")\nif [ -f \"$LIB_DIR/commands.txt\" ] && [ ! -L \"$LIB_DIR/commands.txt\" ]; then\n  while IFS= read -r old; do names+=(\"$old\"); done <\"$LIB_DIR/commands.txt\"\nfi\n\nremoved=0\nseen=\" \"\nfor name in \"${names[@]}\"; do\n  [[ \"$name\" =~ $NAME_RE && \"$name\" == \"$PREFIX.\"* ]] || continue\n  case \"$seen\" in *\" $name \"*) continue ;; esac\n  seen=\"$seen$name \"\n  if [ -e \"$CMD_DIR/$name.json\" ] || [ -L \"$CMD_DIR/$name.json\" ]; then\n    run rm -f -- \"$CMD_DIR/$name.json\"\n    removed=$((removed + 1))\n  fi\ndone\nif [ -L \"$LIB_DIR\" ]; then\n  run rm -f -- \"$LIB_DIR\"\nelif [ -d \"$LIB_DIR\" ]; then\n  run rm -rf -- \"$LIB_DIR\"\nfi\n\nif [ \"$RESTART\" = 1 ]; then run systemctl restart musegadget; fi\nif [ \"$DRY_RUN\" = 1 ]; then\n  say \"Dry run: nothing was changed.\"\nelse\n  say \"Removed $removed commands and $LIB_DIR.\"\nfi\n";

/** The machine check of the Muse gadget pack's zip. */
export const PROVE_CHECK_GADGET_SOURCE: string = "// Checks a Muse gadget pack's zip by machine, with no gadget: it unpacks the zip in a temporary folder, checks every\n// command file against the Linux Gadget SDK's rules, checks the scripts with bash -n and a dry run of install.sh, and\n// prints where it unpacked them so the runner can be run next.\n//   node prove-check-gadget.mjs <pack.zip> <slug> <prefix>\nimport { spawnSync } from \"node:child_process\";\nimport { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport path from \"node:path\";\nimport { inflateRawSync } from \"node:zlib\";\n\nconst [zipPath, slug, prefix] = process.argv.slice(2);\n// The SDK's rules, read Oct 31, 2026 from its README (\"Add your own commands\") and its command loader,\n// linux/src/musegadget/commands.py. The 64-character names, 600 s, 5 s grace and 64 KiB a file come only from the loader,\n// aren't documented and may change (lib/outputs/gadget.ts says which is which).\nconst NAME_RE = /^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$/;\nconst MAX_NAME = 64;\nconst RESERVED = [\"system.\", \"file.\", \"device.\", \"link.\"];\nconst TYPES = [\"string\", \"integer\", \"number\", \"boolean\", \"object\", \"array\"];\nconst KEYS = [\"description\", \"exec\", \"required\", \"optional\", \"timeout_ms\"];\nconst MAX_TIMEOUT_MS = 600_000;\nconst TIMEOUT_GRACE_MS = 5_000;\nconst MAX_FILE_BYTES = 64 * 1024;\nconst REGISTRATION_LIMIT = 256 * 1024;\n\nlet failed = false;\nconst say = (ok, text) => {\n  console.log(`${ok ? \"ok    \" : \"FAILED\"} ${text}`);\n  if (!ok) failed = true;\n  return ok;\n};\n\nfunction readZip(zip) {\n  let end = -1;\n  for (let i = zip.length - 22; i >= 0; i--) {\n    if (zip.readUInt32LE(i) === 0x06054b50) {\n      end = i;\n      break;\n    }\n  }\n  if (end < 0) throw new Error(\"it isn't a zip file\");\n  const files = new Map();\n  let at = zip.readUInt32LE(end + 16);\n  for (let n = zip.readUInt16LE(end + 10); n > 0; n--) {\n    const method = zip.readUInt16LE(at + 10);\n    const packed = zip.readUInt32LE(at + 20);\n    const nameLength = zip.readUInt16LE(at + 28);\n    const offset = zip.readUInt32LE(at + 42);\n    const file = zip.subarray(at + 46, at + 46 + nameLength).toString(\"utf8\");\n    const start = offset + 30 + zip.readUInt16LE(offset + 26) + zip.readUInt16LE(offset + 28);\n    const body = zip.subarray(start, start + packed);\n    files.set(file, method === 8 ? inflateRawSync(body) : Buffer.from(body));\n    at += 46 + nameLength + zip.readUInt16LE(at + 30) + zip.readUInt16LE(at + 32);\n  }\n  return files;\n}\n\nconst isObject = (v) => !!v && typeof v === \"object\" && !Array.isArray(v);\n\n/** What's wrong with one command file, by the SDK's rules, or [] when nothing is. */\nfunction problems(name, bytes, libDir) {\n  const out = [];\n  if (bytes.length > MAX_FILE_BYTES) out.push(`it is over ${MAX_FILE_BYTES} bytes`);\n  if (name.length > MAX_NAME || !NAME_RE.test(name)) out.push(\"its name isn't lowercase words joined by dots\");\n  if (RESERVED.some((r) => name.startsWith(r))) out.push(\"its name starts with a reserved prefix\");\n  if (!name.startsWith(`${prefix}.`)) out.push(`its name doesn't start with ${prefix}.`);\n  let spec;\n  try {\n    spec = JSON.parse(bytes.toString(\"utf8\"));\n  } catch {\n    return [...out, \"it isn't JSON\"];\n  }\n  if (!isObject(spec)) return [...out, \"it isn't a JSON object\"];\n  const unknown = Object.keys(spec).filter((k) => !KEYS.includes(k));\n  if (unknown.length) out.push(`it has unknown keys: ${unknown.join(\", \")}`);\n  if (typeof spec.description !== \"string\" || !spec.description.trim()) out.push(\"it has no description\");\n  const exec = spec.exec;\n  if (!Array.isArray(exec) || !exec.length || !exec.every((a) => typeof a === \"string\" && a)) out.push(\"exec isn't a list of strings\");\n  else {\n    if (!exec[0].startsWith(\"/\")) out.push(\"exec doesn't start with an absolute path\");\n    if (exec.length !== 3 || exec[0] !== `${libDir}/node` || exec[1] !== `${libDir}/runner.cjs`) out.push(`exec doesn't run ${libDir}/runner.cjs with one action`);\n  }\n  const params = {};\n  for (const key of [\"required\", \"optional\"]) {\n    const group = spec[key] ?? {};\n    if (!isObject(group)) {\n      out.push(`${key} isn't an object`);\n      continue;\n    }\n    for (const [field, p] of Object.entries(group)) {\n      const shape = isObject(p) && Object.keys(p).sort().join(\",\") === \"description,type\" && TYPES.includes(p.type) && typeof p.description === \"string\";\n      if (!shape) out.push(`${key}.${field} isn't {type, description} with a known type`);\n      if (Object.hasOwn(params, field)) out.push(`${field} is both required and optional`);\n      params[field] = key;\n    }\n  }\n  const t = spec.timeout_ms ?? 30_000;\n  if (!Number.isInteger(t) || t < 1 || t > MAX_TIMEOUT_MS) out.push(`timeout_ms isn't an integer from 1 to ${MAX_TIMEOUT_MS}`);\n  return out;\n}\n\nlet files;\ntry {\n  files = readZip(readFileSync(zipPath));\n} catch (err) {\n  say(false, `can't read the zip: ${err.message}`);\n  process.exit(1);\n}\nconst folder = `${slug}-muse-gadget`;\nfor (const file of files.keys()) console.log(`      ${file}`);\nsay([...files.keys()].every((f) => f.startsWith(`${folder}/`) && !f.split(\"/\").includes(\"..\") && !f.includes(\"\\\\\")), `every path stays inside ${folder}/`);\nfor (const file of [\"README.md\", \"install.sh\", \"uninstall.sh\", \"runner.cjs\"]) say(files.has(`${folder}/${file}`), `it has ${file}`);\n\nconst dir = mkdtempSync(path.join(tmpdir(), \"gadget-\"));\nfor (const [file, body] of files) {\n  if (!file.startsWith(`${folder}/`) || file.split(\"/\").includes(\"..\")) continue;\n  mkdirSync(path.dirname(path.join(dir, file)), { recursive: true });\n  writeFileSync(path.join(dir, file), body);\n}\nconst root = path.join(dir, folder);\n\nconst libDir = `/usr/local/lib/${prefix}-gadget`;\nconst commands = [...files.keys()].filter((f) => f.startsWith(`${folder}/commands.d/`) && f.endsWith(\".json\"));\nsay(commands.length > 0, `it has ${commands.length} command file${commands.length === 1 ? \"\" : \"s\"}`);\nlet total = 0;\nconst names = [];\nfor (const file of commands) {\n  const name = path.basename(file, \".json\");\n  names.push(name);\n  const bytes = files.get(file);\n  const wrong = problems(name, bytes, libDir);\n  say(!wrong.length, `${name}${wrong.length ? `: ${wrong.join(\"; \")}` : \" follows the SDK's rules\"}`);\n  try {\n    const spec = JSON.parse(bytes.toString(\"utf8\"));\n    total += Buffer.byteLength(JSON.stringify({ [name]: { description: spec.description, required: spec.required ?? {}, optional: spec.optional ?? {}, timeout_ms: (spec.timeout_ms ?? 30_000) + TIMEOUT_GRACE_MS } }));\n  } catch {\n    // Already reported.\n  }\n}\nsay(total <= REGISTRATION_LIMIT, `its registrations take ${Math.ceil(total / 1024)} KiB of the gadget's ${REGISTRATION_LIMIT / 1024} KiB`);\n\nconst install = files.get(`${folder}/install.sh`)?.toString(\"utf8\") ?? \"\";\nconst uninstall = files.get(`${folder}/uninstall.sh`)?.toString(\"utf8\") ?? \"\";\nconst listed = (/^COMMANDS=\\((.*)\\)$/m.exec(install)?.[1] ?? \"\").split(\" \").map((n) => n.replace(/^'|'$/g, \"\")).filter(Boolean);\nsay(listed.length === names.length && listed.every((n) => names.includes(n)), \"install.sh installs exactly the command files in the pack\");\nsay(![install, uninstall].some((s) => /sdk_token|\\/var\\/lib\\/musegadget|mgst_/.test(s)), \"the scripts never touch the SDK token\");\nfor (const file of [\"install.sh\", \"uninstall.sh\"]) {\n  const checked = spawnSync(\"bash\", [\"-n\", path.join(root, file)], { encoding: \"utf8\" });\n  say(checked.status === 0, `bash -n ${file}${checked.status === 0 ? \"\" : `: ${(checked.stderr || \"\").trim().split(\"\\n\").pop()}`}`);\n}\nconst syntax = spawnSync(process.execPath, [\"--check\", path.join(root, \"runner.cjs\")], { encoding: \"utf8\" });\nsay(syntax.status === 0, \"node --check runner.cjs\");\n\n// A dry run under a made-up root changes nothing and needs no sudo.\nconst fake = path.join(dir, \"fake-root\");\nconst dry = spawnSync(\"bash\", [path.join(root, \"install.sh\"), \"--dry-run\", \"--root\", fake, \"--node\", process.execPath], { encoding: \"utf8\" });\nconst would = (dry.stdout || \"\").split(\"\\n\").filter((l) => l.startsWith(\"would run:\"));\nsay(\n  dry.status === 0 && names.every((n) => would.some((l) => l.includes(`commands.d/${n}.json`))),\n  `install.sh --dry-run would add ${names.length} command${names.length === 1 ? \"\" : \"s\"}${dry.status === 0 ? \"\" : `: ${(dry.stderr || \"\").trim().split(\"\\n\").pop()}`}`,\n);\n\nconsole.log(`unpacked to ${root}`);\nprocess.exit(failed ? 1 : 0);\n";
